(* [comment removed for export] *)
Lemma vec_grow M M' v b k stk c B :
  PM.vec_at segs PMSP.T3 PMSP.T4 M v b k stk -> Z.of_nat (length stk) = 2 ^ k -> k <= 10 ->
  0 <= b -> b + 32 * 2 ^ k <= 2 ^ 64 -> 0 <= B -> B + 32 * 2 ^ (k + 1) <= 2 ^ 64 -> B mod 16 = 0 ->
  L5.u64_at segs M' v B -> L5.u64_at segs M' (v + 8) (B + 32 * 2 ^ k + 32) -> L5.u64_at segs M' (v + 16) (B + 32 * 2 ^ (k + 1)) ->
  L5.defined M' B (32 * 2 ^ (k + 1)) ->
  (forall i, 0 <= i < 32 * 2 ^ k -> M' (Z_to_bv 64 (B + i)) = M (Z_to_bv 64 (b + i))) ->
  PM.pstate_at segs M' (B + 32 * 2 ^ k) c ->
