(* [comment removed for export] *)
Lemma parser_upd M M' op ois s m' d' b' k' stk' :
  PM.parser_at segs A PMSP.T3 PMSP.T4 M op ois s -> 0 <= op -> op + 384 <= 2 ^ 64 ->
  L5C.agree_on M M' op 8 -> L5C.agree_on M M' (op + 9) 3 -> L5C.agree_on M M' (op + 16) 344 ->
  PMPK.dkr M M' (op + 8) 8 -> PMPK.dkr M M' (op + 360) 24 ->
  L5.u8_at segs M' (op + 8) m' -> (m' = 0 \/ m' = 1) -> L5.u32_at segs M' (op + 12) d' -> 0 <= d' <= PM.MAX_DEPTH + 1 ->
  PM.vec_at segs PMSP.T3 PMSP.T4 M' (op + 360) b' k' stk' ->
  PMPK.dkr M M' (PM.sr_qc (PM.p_src s)) PM.CHUNK ->
  (forall c n p, PM.p_tb s = PM.VLong c n p -> PMPK.dkr M M' p c) ->
  PM.parser_at segs A PMSP.T3 PMSP.T4 M' op ois (PM.PST m' (PM.p_done s) d' (PM.p_src s) (PM.p_tb s) (PM.p_tg s) b' k' stk').
