  0 <= fst (PM.pot_text L (PM.p_tb s) (PM.p_tg s)) -> 0 <= snd (PM.pot_text L (PM.p_tb s) (PM.p_tg s)) ->
  credit_ok L cr (32 * 2 ^ (PM.p_k s + 1)).
